function toolsFor(role: LoopInput["role"]): Anthropic.Beta.BetaTool[] {
  if (role === "explorer") return [...LOOK_TOOLS, FINISH.explorer];
  return [...WORK_TOOLS, ...TEAM_TOOLS, FINISH[role]];
}

interface LoopInput {
  ctx: AgentContext;
  workspace: Workspace;
  ticketId: string;
  /** An explorer is the read-only helper a coder or reviewer asks with explore. */
  role: "coder" | "reviewer" | "explorer";
  system: string;
  prompt: string;
  /**
   * How many turns this run gets. Unset is the in-process default, forty; a
   * job's loop is handed the ceiling its time budget is worth.
   */
  maxTurns?: number;
  /** Which provider, model and key; unset runs the built-in Claude coder. */
  provider?: ProviderId;
  model?: string;
  apiKey?: string | null;
}

/** A tool call, whichever provider asked for it. */
interface LoopCall {
  id: string;
  name: string;
  input: unknown;
}

interface Turn {
  calls: LoopCall[];
  /** What the model thought and said this turn, besides its tool calls. */
  thoughts: Array<{ kind: "thinking" | "text"; text: string }>;
  stop: "done" | "refusal" | "max_tokens";
  usage: Usage;
}

/** Thrown for a turn worth simply asking again, e.g. a garbled tool input. */
class RetryTurn extends Error {}

/**
 * One provider's side of the conversation. The loop drives it with plain
 * tool calls and results; the conversation keeps its own wire format,
 * which matters for Claude, whose thinking blocks must go back unchanged.
 */
interface Conversation {
  next(): Promise<Turn>;
  toolResults(results: Array<{ id: string; content: string; isError: boolean }>): void;
  say(text: string): void;
  /**
   * Adds a person's words to the turn about to be sent. For Claude they join
   * the tool results' message: two user messages in a row are refused.
   */
  note(text: string): void;
  /**
   * Replaces the transcript with the opening prompt plus `summary`, dropping
   * the tool calls, outputs and thinking that accumulated before it. Used when
   * the transcript grows past a ceiling, so the run keeps working instead of
   * re-sending everything and tripping the token budget.
   */
  compact(summary: string): void;
  /**
   * Swaps the tool results named for the text given, leaving the calls that
   * produced them, and everything the model said, as they were.
   */
  mask(notes: ReadonlyMap<string, string>): void;
}

function addUsage(a: Usage, b: Usage): Usage {
  return {
    model: a.model,
    tokensIn: a.tokensIn + b.tokensIn,
    tokensOut: a.tokensOut + b.tokensOut,
    costTokensIn: (a.costTokensIn ?? a.tokensIn) + (b.costTokensIn ?? b.tokensIn),
    costCents: a.costCents + b.costCents,
  };
}

function usageFrom(
  model: string,
  tokensIn: number,
  tokensOut: number,
  provider?: ProviderId | null,
  costTokensIn = tokensIn,
): Usage {
  return {
    model,
    tokensIn,
    tokensOut,
    costTokensIn,
    costCents: estimateCostCents(model, costTokensIn, tokensOut, provider),
  };
}

function claudeConversation(input: LoopInput, model: string): Conversation {
  const shape = requestShape(model, {
    // The ticket's size when effort follows story points; medium otherwise.
    effort: input.ctx.budget?.effort ?? "medium",
    taskBudgetTokens: advisoryTokens(input.ctx.budget?.tokens.value),
  });
  const messages: Anthropic.Beta.BetaMessageParam[] = [
    { role: "user", content: input.prompt },
  ];
  return {
    async next() {
      let message: Anthropic.Beta.BetaMessage;
      try {
        const stream = anthropicClient(input.apiKey).beta.messages.stream({
          model,
          max_tokens: 64_000,
          system: cachedSystem(input.system),
          ...(shape.thinking ? { thinking: shape.thinking } : {}),
          ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
          output_config: shape.outputConfig,
          betas: shape.betas,
          tools: toolsFor(input.role),
          messages: cachedToHere(messages),
        });
        message = await stream.finalMessage();
      } catch (e) {
        // Eager input streaming hands validation to us, so an unparseable
        // tool input is a turn to re-issue rather than a run to fail. API
        // errors are not: those are real.
        if (!(e instanceof Anthropic.APIError)) throw new RetryTurn(describeError(e));
        throw new Error(describeError(e));
      }
      messages.push({ role: "assistant", content: message.content });
      return {
        thoughts: message.content.flatMap((b): Turn["thoughts"] =>
          b.type === "thinking" && b.thinking.trim()
            ? [{ kind: "thinking" as const, text: b.thinking }]
            : b.type === "text" && b.text.trim()
              ? [{ kind: "text" as const, text: b.text }]
              : [],
        ),
        calls: message.content
          .filter((b): b is Anthropic.Beta.BetaToolUseBlock => b.type === "tool_use")
          .map((b) => ({ id: b.id, name: b.name, input: b.input })),
        stop:
          message.stop_reason === "refusal"
            ? "refusal"
            : message.stop_reason === "max_tokens"
              ? "max_tokens"
              : "done",
        usage: (() => {
          const { tokensIn, costTokensIn } = billedInputTokens(message.usage);
          return usageFrom(model, tokensIn, message.usage.output_tokens, input.provider, costTokensIn);
        })(),
      };
    },
    toolResults(results) {
      messages.push({
        role: "user",
        content: results.map((r) => ({
          type: "tool_result" as const,
          tool_use_id: r.id,
          is_error: r.isError,
          content: r.content,
        })),
      });
    },
    say(text) {
      messages.push({ role: "user", content: text });
    },
    note(text) {
      const last = messages.at(-1);
      if (last?.role === "user" && Array.isArray(last.content)) {
        last.content.push({ type: "text", text });
      } else {
        messages.push({ role: "user", content: text });
      }
    },
    compact(summary) {
      // The opening prompt and the summary become one user turn: two user
      // messages in a row are refused.
      messages.length = 0;
      messages.push({ role: "user", content: `${input.prompt}\n\n${summary}` });
    },
    mask(notes) {
      for (const m of messages) {
        if (m.role !== "user" || !Array.isArray(m.content)) continue;
        for (const block of m.content) {
          const note = block.type === "tool_result" ? notes.get(block.tool_use_id) : undefined;
          if (note !== undefined) (block as { content: unknown }).content = note;
        }
      }
    },
  };
}

/** The same tools, in OpenAI's function format. */
function openAiTools(role: LoopInput["role"]): ToolSpec[] {
  return toolsFor(role).map((t) => ({
    type: "function",
    function: { name: t.name, description: t.description ?? "", parameters: t.input_schema },
  }));
}

function openAiConversation(
  input: LoopInput,
  info: ProviderInfo,
  model: string,
  apiKey: string,
): Conversation {
  const messages: ChatMessage[] = [
    { role: "system", content: input.system },
    { role: "user", content: input.prompt },
  ];
  let advertised: Promise<ModelInfo | undefined> | undefined;
  return {
    async next() {
      advertised ??= advertisedModel(info, apiKey, model, input.ctx.signal);
      const modelInfo = await advertised;
      // The budget can run out while the model list is fetched; do not start a reply after it.
      input.ctx.signal?.throwIfAborted();
      const result = await chat(info, apiKey, {
        model,
        messages,
        tools: openAiTools(input.role),
        // The helper answers a question, the way a chat does.
        ...reasoningFor(info, input.role === "explorer" ? "chat" : input.role, modelInfo, input.ctx.budget?.effort),
        signal: input.ctx.signal,
      }).catch((e: unknown) => {
        throw new Error(e instanceof Error ? e.message : String(e));
      });
      // The provider's whole message goes back, reasoning included: DeepSeek
      // rejects the next turn when a tool turn's reasoning is missing.
      messages.push(result.message);
      return {
        thoughts: [
          ...(result.message.reasoning_content?.trim()
            ? [{ kind: "thinking" as const, text: result.message.reasoning_content }]
            : []),
          ...(result.message.content?.trim()
            ? [{ kind: "text" as const, text: result.message.content }]
            : []),
        ],
        calls: (result.message.tool_calls ?? []).map((c) => {
          let parsed: unknown;
          try {
            parsed = JSON.parse(c.function.arguments || "{}");
          } catch {
            // Garbled arguments fail the tool's own validation, which tells
            // the model exactly what to fix.
            parsed = { unparseable: c.function.arguments };
          }
          return { id: c.id, name: c.function.name, input: parsed };
        }),
        stop: result.finishReason === "length" ? "max_tokens" : "done",
        usage: usageFrom(model, result.tokensIn, result.tokensOut, info.id, result.costTokensIn),
      };
    },
    toolResults(results) {
      for (const r of results) {
        messages.push({
          role: "tool",
          tool_call_id: r.id,
          content: r.isError ? `Error: ${r.content}` : r.content,
        });
      }
    },
    say(text) {
      messages.push({ role: "user", content: text });
    },
    note(text) {
      messages.push({ role: "user", content: text });
    },
    compact(summary) {
      messages.length = 1; // keep the system prompt
      messages.push({ role: "user", content: `${input.prompt}\n\n${summary}` });
    },
    mask(notes) {
      for (const m of messages) {
        const note = m.role === "tool" && m.tool_call_id ? notes.get(m.tool_call_id) : undefined;
        if (note !== undefined) m.content = note;
      }
    },
  };
}

/** What the agent reported. A reviewer's `sendBack` is null for a coder. */
export type LoopResult = CodeChange & { sendBack: string | null };

/**
 * Runs the loop until the agent calls `finish`, the budget stops it, or it
 * runs out of turns. Returns what the agent changed; committing and pushing
 * are the pipeline's job, because they are policy and this is mechanism.
 */
export async function runCodingLoop(
  input: LoopInput,
): Promise<AgentOutcome<LoopResult>> {
  const { ctx, workspace, role, ticketId } = input;
  const info = provider(input.provider ?? "anthropic")!;
  const model = input.model ?? CODER_MODEL;
  const minutes = ctx.budget?.minutes.value;
  const maxTurns = Math.max(
    1,
    Math.round(input.maxTurns ?? (minutes ? turnCeiling(minutes * 60_000) : MAX_TURNS)),
  );
  const startedAt = ctx.startedAt ?? Date.now();
  let total: Usage = { model, tokensIn: 0, tokensOut: 0, costCents: 0 };
  let retries = 0;
  /** The plan as the agent last sent it: the board's progress while it works. */
  let plan: PlanStep[] = [];
  /** The turn the plan last moved, or was last asked about. */
  let planTurn = 0;
  /** The first turn's input tokens: the prompt, tools and system, sent every turn. */
  let baselineIn: number | null = null;
  /** Paths written or edited, kept in the summary when the transcript is compacted. */
  const changedFiles = new Set<string>();
  /** Every tool result sent since the last compaction, for observation masking. */
  let observations: Observation[] = [];

  const fail = (error: string, blocked = false): AgentOutcome<LoopResult> => ({
    ok: false,
    error,
    blocked,
    usage: total,
  });

  const briefed =
    role === "explorer" ? input : { ...input, system: `${input.system.trim()}\n\n${PLANNING_RULES}` };
  let conversation: Conversation;
  if (info.kind === "anthropic") {
    conversation = claudeConversation(briefed, model);
  } else {
    if (!input.apiKey) return fail(`This agent has no ${info.label} API key. Edit it and add one.`, true);
    conversation = openAiConversation(briefed, info, model, input.apiKey);
  }

  const progress = (label: string, iteration: number) => {
    ctx.emit({
      type: "run.progress",
      runId: ctx.runId,
      ticketId,
      // The helper's ctx shows nothing, but the event still names a role.
      role: role === "explorer" ? "coder" : role,
      label,
      // The plan is the progress once there is one, exactly as it is for a CLI
      // agent's run; the turn ceiling is the bar before the first plan lands.
      fraction: planFraction(plan) ?? Math.min(iteration / maxTurns, 0.95),
    });
  };

  // Said before the first model call, not after the first tool call: a turn
  // carries the whole brief and every tool, and a model that thinks takes a
  // while over it. A run that says nothing for its first minute reads as
  // stuck — in a job especially, where there is nothing else to look at.
  progress(role === "reviewer" ? "Reading the pull request" : "Reading the ticket and the repository", 1);

  for (let iteration = 1; iteration <= maxTurns; iteration++) {
    if (ctx.signal.aborted) {
      const { reason } = ctx.signal;
      return fail(
        reason instanceof Error ? reason.message : "Run stopped before the change was finished.",
        true,
      );
    }

    // The run's own limits, between turns: a turn already under way is not
    // cut short, and the next one is not begun past a limit.
    const { budget } = ctx;
    if (budget?.tokens.value != null && budgetTokens(total) >= budget.tokens.value) {
      return fail(tokenLimitNote(budget, budgetTokens(total)), true);
    }
    if (budget?.minutes.value != null && Date.now() - startedAt >= budget.minutes.value * 60_000) {
      return fail(timeLimitNote(budget), true);
    }

    let turn: Turn;
    try {
      turn = await conversation.next();
      retries = 0;
    } catch (e) {
      if (e instanceof RetryTurn && retries++ < 2) continue;
      return fail(e instanceof Error ? e.message : String(e));
    }

    total = addUsage(total, turn.usage);
    await ctx.charge?.(turn.usage);

    for (const thought of turn.thoughts) {
      ctx.emit({
        type: "run.thought",
        runId: ctx.runId,
        ticketId,
        kind: thought.kind,
        text: truncate(thought.text.trim(), MAX_THOUGHT),
      });
    }

    if (turn.stop === "refusal") {
      return fail("The model declined to work on this ticket.", true);
    }
    if (turn.stop === "max_tokens") {
      return fail("The agent's turn was cut off before it finished.");
    }

    if (turn.calls.length === 0) {
      // Ended its turn without finishing. One nudge, then give up: a model
      // that cannot say what it did probably did not do it.
      if (iteration >= maxTurns - 1) break;
      conversation.say(
        "Call finish with a summary once the change is complete, or keep working if it is not.",
      );
      continue;
    }

    const results: Array<{ id: string; content: string; isError: boolean }> = [];

    // Reads and questions change nothing, so the ones before this turn's
    // first command or edit run together; anything after that waits its
    // turn, since it may need to see the change. Neither ever rejects.
    const look = (call: LoopCall) =>
      call.name === "explore" ? explore(call, input) : runTool(call, workspace, ctx);
    const prefetched = new Map<string, Promise<ToolOutcome>>();
    for (const call of turn.calls) {
      if (call.name === "bash" || call.name === "write_file" || call.name === "str_replace") break;
      if (call.name === "read_file" || call.name === "explore") prefetched.set(call.id, look(call));
    }

    // One diff per file per turn, not one per edit: each is a git process.
    const edited = new Set<string>();
    const flushDiffs = async () => {
      for (const path of edited) await emitDiff(workspace, ctx, path);
      edited.clear();
    };

    for (const call of turn.calls) {
      if (call.name === "finish") {
        await flushDiffs();
        const parsed = finishInput.safeParse(call.input);
        if (parsed.success) {
          const blocked = parsed.data.blocked_reason?.trim();
          if (blocked) return fail(blocked, true);
          progress(role === "reviewer" ? "Review complete" : "Change complete", maxTurns);
          return {
            ok: true,
            value: {
              summary: parsed.data.summary,
              detail: parsed.data.detail,
              verifiedWith: parsed.data.verified_with ?? null,
              alreadyDone: parsed.data.already_done ?? false,
              handoff: checkHandoff(parsed.data.for_you),
              followUps: checkFollowUps(parsed.data.follow_ups),
              sendBack: parsed.data.send_back?.trim() || null,
            },
            usage: total,
          };
        }
        results.push({
          id: call.id,
          isError: true,
          content: `finish was malformed: ${parsed.error.issues[0]?.message}`,
        });
        continue;
      }

      // The helper looks and nothing else, whatever tool it names.
      if (role === "explorer" && !LOOK_TOOLS.some((t) => t.name === call.name)) {
        results.push({ id: call.id, isError: true, content: `${call.name} is not available to you.` });
        continue;
      }

      if (call.name === "update_plan") {
        const steps = checkPlan(call.input);
        if (steps) {
          const stamped = steps.map((s): PlanStep => ({ ...s, role: role === "reviewer" ? "reviewer" : "coder" }));
          plan = stamped;
          planTurn = iteration;
          ctx.emit({ type: "ticket.plan", ticketId, steps: stamped });
          // In the feed and the job log as well as the plan itself: without
          // this a plan update is invisible, and a plan that stopped moving
          // is the only sign a run has lost its way that is not a tool call.
          progress(`Plan: ${planLine(steps)}`, iteration);
        }
        results.push({
          id: call.id,
          isError: !steps,
          content: steps
            ? "Plan updated."
            : `update_plan needs 1 to ${MAX_PLAN_STEPS} steps, each with a step and a status.`,
        });
        continue;
      }

      if (call.name === "share_note") {
        const parsed = shareInput.safeParse(call.input);
        if (parsed.success) {
          const note = parsed.data.note.slice(0, MAX_SHARED_NOTE);
          ctx.emit({ type: "repo.note", ticketId, text: note });
          progress(`Shared with the other agents: ${note}`.slice(0, 200), iteration);
        }
        results.push({
          id: call.id,
          isError: !parsed.success,
          content: parsed.success
            ? "Shared with the agents on this repository's other tickets."
            : "share_note needs a note.",
        });
        continue;
      }

      if (call.name === "rate_note") {
        const parsed = rateInput.safeParse(call.input);
        if (parsed.success) {
          ctx.emit({ type: "repo.note.rated", ticketId, noteSeq: parsed.data.note, verdict: parsed.data.verdict });
        }
        results.push({
          id: call.id,
          isError: !parsed.success,
          content: parsed.success ? "Noted." : "rate_note needs a note number and a verdict of helped or outdated.",
        });
        continue;
      }

      const outcome = await (prefetched.get(call.id) ?? look(call));
      // The helper's turns were charged as they ran; the run's total carries them.
      if (outcome.usage) total = addUsage(total, outcome.usage);
      progress(outcome.label, iteration);
      results.push({ id: call.id, isError: outcome.isError, content: truncate(outcome.content) });
      if (call.name === "write_file" || call.name === "str_replace") {
        const path = (call.input as { path?: unknown } | null)?.path;
        if (typeof path === "string") {
          changedFiles.add(path);
          if (!outcome.isError) edited.add(path);
        }
      }
    }

    await flushDiffs();
    conversation.toolResults(results);
    for (const r of results) {
      const tool = turn.calls.find((c) => c.id === r.id)?.name ?? "tool";
      observations.push({ id: r.id, tool, turn: iteration, size: r.content.length, masked: false });
    }

    // Outputs the agent has moved past are cleared in one batch once enough
    // has piled up, so every later turn re-sends less and compaction, which
    // drops everything, comes later or not at all.
    const moved = staleObservations(observations, iteration);
    if (moved.length > 0) {
      conversation.mask(new Map(moved.map((o) => [o.id, maskedNote(o)])));
      for (const o of moved) o.masked = true;
    }

    // The person watching can stop the run or steer it between turns.
    const heard = await ctx.interrupts?.().catch(() => null);
    if (heard?.stopped) return fail(heard.stopped, true);
    for (const note of heard?.notes ?? []) {
      conversation.note(
        `A note from the person watching this ticket. Take it into account from here on:\n\n${note}`,
      );
    }
    if (heard?.shared?.length) {
      conversation.note(`${SHARED_NOTES_INTRO}\n\n${heard.shared.map((n) => `- ${n}`).join("\n")}`);
    }

    // A plan that stopped moving is how the person watching tells a slow run
    // from a stuck one, and a model deep in its work forgets it. Asked as a
    // fact about the board, not as the rule it already has.
    const stale = iteration - planTurn;
    if (role !== "explorer" && stale >= PLAN_NUDGE_TURNS) {
      planTurn = iteration;
      conversation.note(planNudge(plan, stale));
    }

    // A transcript that has grown far past its opening prompt is compacted
    // here, so the run keeps working instead of re-sending everything and
    // tripping the token ceiling. Growth is measured on the last turn's input
    // tokens, which is the transcript exactly as it was sent.
    const grown = baselineIn === null ? 0 : turn.usage.tokensIn - baselineIn;
    if (baselineIn === null) {
      baselineIn = turn.usage.tokensIn;
    } else if (grown > compactThreshold(ctx.budget?.tokens.value)) {
      progress("Compacting the conversation to stay within budget", iteration);
      conversation.compact(compactionSummary(plan, changedFiles, iteration));
      observations = [];
      baselineIn = null;
    }
  }

  return fail(
    `The agent did not converge in ${maxTurns} turn${maxTurns === 1 ? "" : "s"}. This needs a human.`,
    true,
  );
}

interface ToolOutcome {
  content: string;
  isError: boolean;
  label: string;
  /** What a tool that calls a model used: explore's helper. */
  usage?: Usage;
}

/**
 * A question answered by a helper agent: its own short loop, on the same
 * provider and key, read-only, and on a cheaper model where Formic knows
 * one. Only the answer comes back, so the searching and reading behind it
 * never enter the asking agent's conversation, which every later turn
 * re-sends.
 */
async function explore(call: LoopCall, input: LoopInput): Promise<ToolOutcome> {
  const parsed = exploreInput.safeParse(call.input);
  if (!parsed.success) return invalid(parsed.error.issues[0]?.message, "explore");
  const { question } = parsed.data;
  const label = `Asked a helper: ${question.slice(0, 60)}`;
  const { ctx } = input;
  const info = provider(input.provider ?? "anthropic");
  const model = info?.kind === "anthropic" ? HELPER_MODEL : (input.model ?? CODER_MODEL);
  const outcome = await runCodingLoop({
    ...input,
    role: "explorer",
    system: EXPLORER_BRIEF,
    prompt: question,
    model,
    maxTurns: EXPLORE_TURNS,
    ctx: {
      runId: ctx.runId,
      projectId: ctx.projectId,
      signal: ctx.signal,
      // Its turns count against the run's budget as they happen; what it
      // thinks and reads is not the board's to show.
      charge: ctx.charge,
      emit: () => {},
      startedAt: ctx.startedAt,
      budget: {
        minutes: ctx.budget?.minutes ?? { value: null, requested: null, clamp: null },
        tokens: { value: EXPLORE_TOKENS, requested: null, clamp: null },
        attempts: { value: null, requested: null, clamp: null },
        maxCents: null,
        effort: "low",
        enforcement: { minutes: "between-turns", tokens: "between-turns", attempts: "between-turns" },
      },
    },
  }).catch(
    (e: unknown): AgentOutcome<LoopResult> => ({
      ok: false,
      error: e instanceof Error ? e.message : String(e),
      blocked: false,
      usage: { model, tokensIn: 0, tokensOut: 0, costCents: 0 },
    }),
  );
  return outcome.ok
    ? { content: outcome.value.detail, isError: false, label, usage: outcome.usage }
    : {
        content: `The helper could not answer: ${outcome.error} Search and read it yourself.`,
        isError: true,
        label,
        usage: outcome.usage,
      };
}

/** A value as one shell word. */
function shellWord(value: string): string {
  return `'${value.replaceAll("'", `'\\''`)}'`;
}

/** At most this many lines of a listing or a search come back. */
const MAX_LOOK_LINES = 300;

async function runTool(
  call: LoopCall,
  workspace: Workspace,
  ctx: AgentContext,
): Promise<ToolOutcome> {
  try {
    switch (call.name) {
      case "bash": {
        const parsed = bashInput.safeParse(call.input);
        if (!parsed.success) {
          return invalid(parsed.error.issues[0]?.message, "bash");
        }
        const log = commandLog(ctx);
        const result = await workspace
          .exec(parsed.data.command, {
            timeoutMs: (parsed.data.timeout_seconds ?? 300) * 1000,
            signal: ctx.signal,
            onStdout: (line) => log.line({ stream: "stdout", line }),
            onStderr: (line) => log.line({ stream: "stderr", line }),
          })
          .finally(() => log.end());
        const stdout = tidyOutput(result.stdout);
        const stderr = tidyOutput(result.stderr);
        const body = [
          `exit ${result.exitCode}${result.timedOut ? " (timed out)" : ""}`,
          stdout && `stdout:\n${stdout}`,
          stderr && `stderr:\n${stderr}`,
        ]
          .filter(Boolean)
          .join("\n");
        return {
          content: body,
          // A non-zero exit is information, not a tool failure. Marking it an
          // error would tell the model its command was malformed when in fact
          // the tests it just ran are red, which is the thing it needs to see.
          isError: false,
          label: `$ ${parsed.data.command.slice(0, 60)}`,
        };
      }

      case "read_file": {
        const parsed = readInput.safeParse(call.input);
        if (!parsed.success) {
          return invalid(parsed.error.issues[0]?.message, "read_file");
        }
        const { path, offset, limit } = parsed.data;
        const contents = await workspace.readFile(path);
        return {
          content: readWindow(contents, offset, limit),
          isError: false,
          label: offset || limit ? `Reading ${path} from line ${offset ?? 1}` : `Reading ${path}`,
        };
      }

      case "list_files":
      case "search": {
        const listed = call.name === "list_files";
        const parsed = listed ? listInput.safeParse(call.input) : searchInput.safeParse(call.input);
        if (!parsed.success) return invalid(parsed.error.issues[0]?.message, call.name);
        const under = parsed.data.path?.trim() ? ` -- ${shellWord(parsed.data.path.trim())}` : "";
        const command = listed
          ? `git ls-files --cached --others --exclude-standard${under}`
          : `git grep --untracked -n -I -E -e ${shellWord((parsed.data as { pattern: string }).pattern)}${under}`;
        const result = await workspace.exec(`${command} | head -n ${MAX_LOOK_LINES + 1}`, {
          timeoutMs: 60_000,
          signal: ctx.signal,
        });
        const lines = result.stdout.split("\n").filter(Boolean);
        const body =
          lines.length === 0
            ? listed
              ? "No files there."
              : "No matches."
            : lines.length > MAX_LOOK_LINES
              ? `${lines.slice(0, MAX_LOOK_LINES).join("\n")}\n[More than ${MAX_LOOK_LINES} lines: narrow it down.]`
              : lines.join("\n");
        return { content: body, isError: false, label: listed ? "Listing files" : "Searching" };
      }

      case "write_file": {
        const parsed = writeInput.safeParse(call.input);
        if (!parsed.success) {
          return invalid(parsed.error.issues[0]?.message, "write_file");
        }
        await workspace.writeFile(parsed.data.path, parsed.data.contents);
        return {
          content: `Wrote ${parsed.data.path}.${outsideNote(workspace, parsed.data.path)}`,
          isError: false,
          label: `Writing ${parsed.data.path}`,
        };
      }

      case "str_replace": {
        const parsed = replaceInput.safeParse(call.input);
        if (!parsed.success) {
          return invalid(parsed.error.issues[0]?.message, "str_replace");
        }
        const { path, old_text, new_text } = parsed.data;
        const before = await workspace.readFile(path);
        const first = before.indexOf(old_text);
        if (first === -1) {
          return {
            content: `old_text was not found in ${path}. Read the file and match it exactly.`,
            isError: true,
            label: `Editing ${path}`,
          };
        }
        if (before.indexOf(old_text, first + 1) !== -1) {
          return {
            content: `old_text appears more than once in ${path}. Include enough surrounding context to make it unique.`,
            isError: true,
            label: `Editing ${path}`,
          };
        }
        await workspace.writeFile(
          path,
          before.slice(0, first) + new_text + before.slice(first + old_text.length),
        );
        return { content: `Edited ${path}.${outsideNote(workspace, path)}`, isError: false, label: `Editing ${path}` };
      }

      default:
        return { content: `Unknown tool ${call.name}.`, isError: true, label: call.name };
    }
  } catch (e) {
    if (e instanceof ScopeError) {
      // The one error worth phrasing carefully: it is the mechanism behind
      // the concurrency claim, and the agent can recover from it.
      return { content: e.message, isError: true, label: "Scope violation" };
    }
    return {
      content: e instanceof Error ? e.message : String(e),
      isError: true,
      label: call.name,
    };
  }
}

/** What a write outside the ticket's file scope means, told as it happens. */
function outsideNote(workspace: Workspace, path: string): string {
  if (!workspace.outsideScope?.(path)) return "";
  return " It is outside this ticket's file scope. That is fine when the right change needs it: Formic asks the person to add it to the scope before your work goes further. Where an equally good change fits inside the scope, prefer that.";
}

function invalid(detail: string | undefined, tool: string): ToolOutcome {
  return {
    content: `${tool} input was invalid: ${detail ?? "unknown field"}`,
    isError: true,
    label: tool,
  };
}

async function emitDiff(
  workspace: Workspace,
  ctx: AgentContext,
  path: string,
): Promise<void> {
  const patch = await workspace.diff(path).catch(() => "");
  if (!patch) return;
  ctx.emit({
    type: "run.diff",
    runId: ctx.runId,
    path,
    patch: truncate(patch, 8_000),
  });
}
