/** Image types the API accepts as an image content block. Anything else is inlined as text instead. */
const IMAGE_MEDIA_TYPES = new Set(["image/jpeg", "image/png", "image/gif", "image/webp"]);

/**
 * An attachment as the model sees it: an image ahead of the request becomes an
 * image content block, a text file its own text block. Both drafting agents
 * ground their reading in these the way they ground it in the request text.
 */
function attachmentBlocks(attachments: AgentAttachment[]): Anthropic.Beta.BetaContentBlockParam[] {
  const blocks: Anthropic.Beta.BetaContentBlockParam[] = [];
  for (const a of attachments) {
    if (a.kind === "image" && a.base64 && IMAGE_MEDIA_TYPES.has(a.mimeType)) {
      blocks.push({
        type: "image",
        source: {
          type: "base64",
          media_type: a.mimeType as "image/jpeg" | "image/png" | "image/gif" | "image/webp",
          data: a.base64,
        },
      });
    } else if (a.kind === "file" && a.text) {
      blocks.push({ type: "text", text: `Attached file "${a.filename}":\n\n${a.text}` });
    }
  }
  return blocks;
}

/**
 * Real agents.
 *
 * Model choice: Opus 5 with adaptive thinking. The PRD in the repository root
 * names Claude 3.5 Sonnet, which is several generations stale; the model id
 * lives in MODELS below so changing it is one edit rather than a grep.
 *
 * Every call opts into server-side refusal fallbacks. A safety classifier
 * declining a request returns HTTP 200 with stop_reason "refusal", and without
 * a fallback that surfaces as an agent silently producing nothing.
 */

export const MODELS = {
  /** PRD drafting. The least demanding of the pipelines. */
  product: "claude-sonnet-5",
  /** Decomposition and file-scope isolation. The hard one. */
  architect: "claude-opus-5",
  /** Aggregating merged diffs into a readable document. */
  showcase: "claude-sonnet-5",
} as const;

/** One client per API key: a preset may bring its own. */
const clients = new Map<string, Anthropic>();

/** A preset's own key, or the server's. */
export function anthropicClient(apiKey?: string | null): Anthropic {
  // The server's key is for local development only. Signed in with GitHub,
  // an agent runs on the key its template carries or not at all.
  const key = apiKey || (authMode() === "local" ? env().ANTHROPIC_API_KEY : undefined);
  if (!key) {
    throw new Error("This agent has no Anthropic API key. Edit it and add one.");
  }
  let c = clients.get(key);
  if (!c) {
    c = new Anthropic({ apiKey: key });
    clients.set(key, c);
  }
  return c;
}

const EPHEMERAL = { type: "ephemeral" } as const;

/**
 * A system prompt the API caches, along with the tools ahead of it. The
 * request is stateless, so the prompt is sent every turn; cached, it is not
 * processed again until it changes, which is also when the cache refreshes.
 */
export function cachedSystem(text: string): Array<{
  type: "text";
  text: string;
  cache_control: typeof EPHEMERAL;
}> {
  return [{ type: "text", text, cache_control: EPHEMERAL }];
}

/**
 * The conversation with a cache breakpoint on its last block, so the next
 * turn reads everything before it from the cache instead of reprocessing a
 * transcript that only ever grows. Only the copy sent carries the marker:
 * the API allows four, and an agentic loop runs for dozens of turns.
 */
export function cachedToHere<M extends { content: unknown }>(messages: M[]): M[] {
  const last = messages.at(-1);
  if (!last) return messages;
  const blocks =
    typeof last.content === "string"
      ? [{ type: "text", text: last.content }]
      : (last.content as Array<Record<string, unknown>>);
  if (blocks.length === 0) return messages;
  const marked = [...blocks.slice(0, -1), { ...blocks.at(-1), cache_control: EPHEMERAL }];
  return [...messages.slice(0, -1), { ...last, content: marked }];
}

/**
 * Input tokens as billed with caching: a cache write costs a quarter more
 * than plain input, a cache read a tenth. `input_tokens` alone leaves both
 * out, which would make every cached turn look nearly free to the budget.
 */
export function billedInputTokens(usage: {
  input_tokens?: number | null;
  cache_creation_input_tokens?: number | null;
  cache_read_input_tokens?: number | null;
}): { tokensIn: number; costTokensIn: number } {
  const plain = usage.input_tokens ?? 0;
  const written = usage.cache_creation_input_tokens ?? 0;
  const read = usage.cache_read_input_tokens ?? 0;
  return {
    tokensIn: plain + written + read,
    costTokensIn: plain + written * 1.25 + read * 0.1,
  };
}

export function usageFrom(
  model: string,
  usage: { input_tokens?: number; output_tokens?: number } | null | undefined,
): Usage {
  const tokensIn = usage?.input_tokens ?? 0;
  const tokensOut = usage?.output_tokens ?? 0;
  return {
    model,
    tokensIn,
    tokensOut,
    costCents: estimateCostCents(model, tokensIn, tokensOut),
  };
}

function failure(
  model: string,
  error: string,
  blocked = false,
  usage?: Usage,
): AgentOutcome<never> {
  return {
    ok: false,
    error,
    blocked,
    usage: usage ?? { model, tokensIn: 0, tokensOut: 0, costCents: 0 },
  };
}

/**
 * Turns an SDK error into something a card can display: a rejected key, an
 * account out of credit, a rate limit and until when, an overloaded API.
 * Shared with the coding loop, so every Claude agent says it the same way.
 */
export function describeError(e: unknown): string {
  if (e instanceof APIConnectionError) {
    return "Could not reach the Anthropic API.";
  }
  if (e instanceof APIError) {
    return describeProviderError({
      label: "The Anthropic API",
      status: e.status ?? null,
      message: e.message,
      retryAfter: e.headers?.get("retry-after") ?? null,
    });
  }
  if (e instanceof Error) return e.message;
  return "Unknown agent failure.";
}

export class AnthropicProductAgent implements ProductAgent {
  constructor(private readonly config: AgentConfig = {}) {}

  async draftPrd(
    ctx: AgentContext,
    input: { epicId: string; rawRequest: string; attachments: AgentAttachment[] },
  ): Promise<
    AgentOutcome<
      | { kind: "prd"; title: string; prd: Prd }
      | { kind: "reroute"; reason: string; ticket: DraftTicket }
    >
  > {
    const model = this.config.model ?? MODELS.product;
    const shape = requestShape(model, { effort: "medium" });

    const outputSchema = z.object({
      title: z.string().describe("A short imperative Epic title, under 80 characters."),
      prd: prdSchema,
    });

    try {
      const stream = anthropicClient(this.config.apiKey).beta.messages.stream({
        model,
        max_tokens: 8_000,
        system: withProductConventions(this.config.brief ?? PRODUCT_BRIEF),
        ...(shape.thinking ? { thinking: shape.thinking } : {}),
        ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
        betas: shape.betas,
        output_config: { ...shape.outputConfig, format: zodOutputFormat(outputSchema) },
        messages: [
          {
            role: "user",
            content: [
              ...attachmentBlocks(input.attachments),
              { type: "text", text: `Raw feature request:\n\n${input.rawRequest}` },
            ],
          },
        ],
      });

      // Stream the document into the drawer as it is written. Most of the
      // perceived quality of this feature is that it fills in rather than
      // appearing after a long blank pause.
      stream.on("text", (delta) => {
        ctx.emit({
          type: "epic.prd",
          epicId: input.epicId,
          delta,
          done: false,
        });
      });

      const message = await stream.finalMessage();
      ctx.emit({ type: "epic.prd", epicId: input.epicId, delta: "", done: true });

      const usage = usageFrom(model, message.usage);

      if (message.stop_reason === "refusal") {
        return failure(
          model,
          "The model declined this request. Rephrase the backlog item.",
          true,
          usage,
        );
      }
      if (message.stop_reason === "max_tokens") {
        return failure(model, "The PRD was cut off before it finished.", false, usage);
      }

      const text = message.content
        .filter((b): b is Anthropic.TextBlock => b.type === "text")
        .map((b) => b.text)
        .join("");

      const parsed = outputSchema.safeParse(JSON.parse(text));
      if (!parsed.success) {
        return failure(
          model,
          `The Product Agent returned a malformed PRD: ${parsed.error.issues[0]?.message}`,
          false,
          usage,
        );
      }

      return { ok: true, value: { kind: "prd", ...parsed.data }, usage };
    } catch (e) {
      return failure(model, describeError(e));
    }
  }
}

export class AnthropicArchitectAgent implements ArchitectAgent {
  constructor(private readonly config: AgentConfig = {}) {}

  async decompose(
    ctx: AgentContext,
    input: {
      epicId: string;
      title: string;
      prd: Prd;
      repoTree: string[];
      existing?: ExistingTicket[];
      instructions?: string[];
      maxAttempts?: number;
    },
  ): Promise<AgentOutcome<DraftTicket[]>> {
    const maxAttempts = input.maxAttempts ?? ATTEMPT_DEFAULTS.decomposition;
    const model = this.config.model ?? MODELS.architect;
    const shape = requestShape(model, { effort: "medium" });
    const messages: Anthropic.Beta.BetaMessageParam[] = [
      {
        role: "user",
        content: [
          `Epic: ${input.title}`,
          "",
          "PRD:",
          JSON.stringify(input.prd, null, 2),
          "",
          "The repository's layout, each directory with its files:",
          input.repoTree.join("\n") || "(empty repository)",
          decompositionGuidance(input.existing, input.instructions),
        ].join("\n"),
      },
    ];

    let total: Usage = { model, tokensIn: 0, tokensOut: 0, costCents: 0 };

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      if (ctx.signal.aborted) {
        return failure(model, "Run stopped before decomposition finished.", true, total);
      }

      ctx.emit({
        type: "run.progress",
        runId: ctx.runId,
        ticketId: null,
        role: "architect",
        label: attempt === 1 ? "Decomposing epic" : `Correcting the graph (attempt ${attempt})`,
        fraction: attempt / maxAttempts,
      });

      let message: Anthropic.Beta.BetaMessage;
      try {
        message = await anthropicClient(this.config.apiKey).beta.messages.create({
          model,
          max_tokens: 16_000,
          system: withPlanningConventions(this.config.brief ?? ARCHITECT_BRIEF),
          ...(shape.thinking ? { thinking: shape.thinking } : {}),
          ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
          output_config: {
            ...shape.outputConfig,
            format: zodOutputFormat(decompositionSchema),
          },
          betas: shape.betas,
          messages,
        });
      } catch (e) {
        return failure(model, describeError(e), false, total);
      }

      const usage = usageFrom(model, message.usage);
      total = {
        model,
        tokensIn: total.tokensIn + usage.tokensIn,
        tokensOut: total.tokensOut + usage.tokensOut,
        costCents: total.costCents + usage.costCents,
      };

      if (message.stop_reason === "refusal") {
        return failure(model, "The model declined to decompose this Epic.", true, total);
      }

      const text = message.content
        .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === "text")
        .map((b) => b.text)
        .join("");

      let raw: unknown;
      try {
        raw = JSON.parse(text);
      } catch {
        raw = null;
      }
      const checked = checkDecomposition(raw);
      if (checked.ok) return { ok: true, value: checked.tickets, usage: total };

      messages.push(
        { role: "assistant", content: text },
        { role: "user", content: checked.correction },
      );
    }

    return failure(
      model,
      `The Architect Agent could not produce a valid dependency graph in ${maxAttempts} attempts. This Epic needs a human to split it.`,
      true,
      total,
    );
  }

  async draftTicket(
    ctx: AgentContext,
    input: { rawRequest: string; repoTree: string[]; attachments: AgentAttachment[] },
  ): Promise<
    AgentOutcome<{ kind: "ticket"; ticket: DraftTicket } | { kind: "reroute"; reason: string }>
  > {
    const model = this.config.model ?? MODELS.architect;
    const shape = requestShape(model, { effort: "medium" });

    try {
      const message = await anthropicClient(this.config.apiKey).beta.messages.create({
        model,
        max_tokens: 8_000,
        system: withPlanningConventions(this.config.brief ?? ARCHITECT_BRIEF),
        ...(shape.thinking ? { thinking: shape.thinking } : {}),
        ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
        output_config: { ...shape.outputConfig, format: zodOutputFormat(ticketOrRerouteSchema) },
        betas: shape.betas,
        messages: [
          {
            role: "user",
            content: [
              ...attachmentBlocks(input.attachments),
              {
                type: "text",
                text: [
                  "Raw feature request:",
                  input.rawRequest,
                  "",
                  "The repository's layout, each directory with its files:",
                  input.repoTree.join("\n") || "(empty repository)",
                ].join("\n"),
              },
            ],
          },
        ],
      });

      const usage = usageFrom(model, message.usage);

      if (message.stop_reason === "refusal") {
        return failure(model, "The model declined to draft this ticket.", true, usage);
      }

      const text = message.content
        .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === "text")
        .map((b) => b.text)
        .join("");

      const parsed = ticketOrRerouteSchema.safeParse(JSON.parse(text));
      if (!parsed.success) {
        return failure(
          model,
          `The Architect Agent returned a malformed ticket: ${parsed.error.issues[0]?.message}`,
          false,
          usage,
        );
      }

      if ("kind" in parsed.data) {
        return { ok: true, value: { kind: "reroute", reason: parsed.data.reason }, usage };
      }

      return { ok: true, value: { kind: "ticket", ticket: toDraftTicket(parsed.data) }, usage };
    } catch (e) {
      return failure(model, describeError(e));
    }
  }
}

/** The Reviewer Agent's pick among a ticket's scouts, on Claude. */
export async function compareScoutsOnClaude(
  config: AgentConfig,
  ctx: AgentContext,
  input: { task: CoderTask; candidates: ScoutCandidate[] },
): Promise<AgentOutcome<ScoutVerdict>> {
  const model = config.model ?? CODER_MODEL;
  const shape = requestShape(model, { effort: "medium" });
  try {
    const message = await anthropicClient(config.apiKey).beta.messages.create(
      {
        model,
        max_tokens: 4_000,
        system: JUDGE_BRIEF,
        ...(shape.thinking ? { thinking: shape.thinking } : {}),
        ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
        output_config: { ...shape.outputConfig, format: zodOutputFormat(scoutVerdictSchema) },
        betas: shape.betas,
        messages: [{ role: "user", content: judgePrompt(input.task, input.candidates) }],
      },
      { signal: ctx.signal },
    );
    const usage = usageFrom(model, message.usage);
    if (message.stop_reason === "refusal") return failure(model, "The model declined to compare the scouts.", true, usage);
    const text = message.content
      .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === "text")
      .map((b) => b.text)
      .join("");
    const verdict = acceptVerdict(JSON.parse(text), input.candidates);
    if (typeof verdict === "string") return failure(model, verdict, false, usage);
    return { ok: true, value: verdict, usage };
  } catch (e) {
    return failure(model, describeError(e));
  }
}

export class AnthropicShowcaseAgent implements ShowcaseAgent {
  constructor(private readonly config: AgentConfig = {}) {}

  async summarize(
    ctx: AgentContext,
    input: {
      epicId: string;
      title: string;
      prd: Prd | null;
      ticketSummaries: Array<{ key: string; title: string; summary: string }>;
    },
  ): Promise<AgentOutcome<string>> {
    const model = this.config.model ?? MODELS.showcase;
    const shape = requestShape(model, { effort: "medium" });

    try {
      // Per-PR summaries are written at merge time, so this aggregates short
      // text rather than raw diffs. A large Epic would otherwise blow the
      // context on diff noise.
      const message = await anthropicClient(this.config.apiKey).beta.messages.create({
        model,
        max_tokens: 8_000,
        system: this.config.brief ?? SHOWCASE_BRIEF,
        ...(shape.thinking ? { thinking: shape.thinking } : {}),
        ...(shape.fallbacks ? { fallbacks: shape.fallbacks } : {}),
        betas: shape.betas,
        messages: [
          {
            role: "user",
            content: [
              `Epic: ${input.title}`,
              input.prd ? `\nOriginal intent: ${input.prd.summary}` : "",
              "",
              "Merged tickets:",
              ...input.ticketSummaries.map(
                (t) => `- ${t.key} ${t.title}: ${t.summary}`,
              ),
            ].join("\n"),
          },
        ],
      });

      const usage = usageFrom(model, message.usage);

      if (message.stop_reason === "refusal") {
        return failure(model, "The model declined to write this showcase.", true, usage);
      }

      const markdown = message.content
        .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === "text")
        .map((b) => b.text)
        .join("")
        .trim();

      if (!markdown) {
        return failure(model, "The showcase came back empty.", false, usage);
      }

      ctx.emit({ type: "epic.showcase", epicId: input.epicId, markdown });
      return { ok: true, value: markdown, usage };
    } catch (e) {
      return failure(model, describeError(e));
    }
  }
}
