import "server-only";

import { z } from "zod";
import { normalizeRepo } from "./repo";

/**
 * Validated server-side configuration.
 *
 * Nothing here is ever imported from a client component: the `server-only`
 * guard turns that into a build error rather than a runtime leak. Values are
 * read lazily so a missing optional credential degrades the feature that needs
 * it instead of failing the whole process at import time.
 */

const schema = z.object({
  DATABASE_URL: z.string().optional(),
  ANTHROPIC_API_KEY: z.string().optional(),
  GITHUB_TOKEN: z.string().optional(),
  GITHUB_REPO: z
    .string()
    .regex(/^[\w.-]+\/[\w.-]+$/, "Expected owner/repo")
    .optional(),
  GITHUB_BASE_BRANCH: z.string().default("main"),
  /** Shared secret for the GitHub webhook receiver. See PROT-07. */
  GITHUB_WEBHOOK_SECRET: z.string().optional(),
  /**
   * Where the Reviewer Agent merges. "base" is each project's own base
   * branch, so Done means the code is there; "integration" holds agent work
   * on formic/integration until a person promotes it.
   */
  MERGE_TARGET: z.enum(["integration", "base"]).default("base"),
  E2B_API_KEY: z.string().optional(),
  /** Sandbox minutes per person per month on E2B_API_KEY, for people with no key of their own. */
  E2B_FALLBACK_MINUTES_PER_USER: z.coerce.number().int().min(0).default(30),
  SANDBOX_PROVIDER: z.enum(["e2b", "local"]).default("local"),
  AGENT_PROVIDER: z.enum(["anthropic", "mock"]).optional(),
  /** Where alerts (error spikes, smoke-test and health failures) are posted. See AUD-10. */
  ALERT_WEBHOOK_URL: z.string().url().optional(),
});

export type Env = z.infer<typeof schema>;

let cached: Env | null = null;

/**
 * Vercel's env var UI takes a value verbatim: pasting `SANDBOX_PROVIDER="local"`
 * straight from .env.example (quotes included, as the file's own syntax
 * shows them) sets the value to the five characters `"local"`, not `local`.
 * Stripping one matching pair of surrounding quotes tolerates that without
 * weakening validation of the actual value.
 */
function unquote(value: string): string {
  return value.match(/^(['"])([\s\S]*)\1$/)?.[2] ?? value;
}

function cleanedProcessEnv(): Record<string, string | undefined> {
  const out: Record<string, string | undefined> = {};
  for (const [key, value] of Object.entries(process.env)) {
    out[key] = typeof value === "string" ? unquote(value.trim()) : value;
  }
  return out;
}

let warnings: string[] = [];

/**
 * Every key here is optional or defaulted, so a malformed value is dropped
 * (falling back to "unset" or its default) and reported, never thrown. One
 * bad optional variable used to 500 every route that read config, which is
 * the opposite of "each credential unlocks one layer".
 */
export function env(): Env {
  if (cached) return cached;

  const input = cleanedProcessEnv();
  if (input.GITHUB_REPO) {
    input.GITHUB_REPO = normalizeRepo(input.GITHUB_REPO) ?? input.GITHUB_REPO;
  }

  let parsed = schema.safeParse(input);
  const found: string[] = [];
  if (!parsed.success) {
    for (const issue of parsed.error.issues) {
      const key = String(issue.path[0]);
      found.push(`${key} is invalid and was ignored: ${issue.message}`);
      delete input[key];
    }
    parsed = schema.safeParse(input);
    if (!parsed.success) throw new Error("Unreachable: every config key is optional.");
  }

  for (const message of found) console.warn(`[formic] config: ${message}`);
  warnings = found;
  cached = parsed.data;
  return cached;
}

/** Config problems found by env(), for /api/health. */
export function configWarnings(): string[] {
  env();
  return warnings;
}

export class MissingCredentialError extends Error {
  constructor(
    readonly key: string,
    readonly feature: string,
  ) {
    super(
      `${feature} needs ${key}, which is not configured. See .env.example.`,
    );
    this.name = "MissingCredentialError";
  }
}

export function requireCredential(
  key:
    | "ANTHROPIC_API_KEY"
    | "GITHUB_TOKEN"
    | "E2B_API_KEY"
    | "GITHUB_REPO"
    | "GITHUB_WEBHOOK_SECRET",
  feature: string,
): string {
  const value = env()[key];
  if (!value) throw new MissingCredentialError(key, feature);
  return value;
}

/**
 * A clone URL carrying the GitHub credential. Built at the point of use and
 * never stored, so it cannot end up in a database column or an event payload.
 */
export function authenticatedCloneUrl(repoFullName: string): string {
  const token = requireCredential("GITHUB_TOKEN", "Cloning the target repository");
  return `https://x-access-token:${token}@github.com/${repoFullName}.git`;
}

export function resetEnvCache(): void {
  cached = null;
  warnings = [];
}
