import { AGENT_ROLES, type PlanStep } from "./entities";
import type { ColumnId } from "./status";

/**
 * Everything the client learns about asynchronously. Delivered over SSE by
 * PROT-10; persisted to the `event` table so a reconnecting client can replay
 * from a cursor instead of showing a gap.
 */

export type FormicEvent =
  | {
      type: "card.status";
      cardId: string;
      kind: "epic" | "ticket";
      status: string;
      stalledIn: string | null;
      stage: number;
      blockedReason: string | null;
    }
  | {
      type: "card.created";
      cardId: string;
      kind: "epic" | "ticket";
      epicId: string | null;
    }
  | {
      /**
       * A card is gone: an Epic a person deleted, with every ticket under
       * it, or a ticket replaced when its Epic was broken down again.
       */
      type: "card.deleted";
      cardId: string;
      kind: "epic" | "ticket";
      /** The GitHub issues that tracked it and its tickets, to close. */
      issueNumbers: number[];
    }
  | {
      /** A request moved to another column: rerouteFrom/rerouteReason changed. */
      type: "card.rerouted";
      cardId: string;
      kind: "epic" | "ticket";
      from: ColumnId;
      to: ColumnId;
      reason: string;
    }
  | {
      /** A Queen was placed on a card. */
      type: "card.queen";
      cardId: string;
      kind: "epic" | "ticket";
    }
  | {
      type: "epic.prd";
      epicId: string;
      /** Incremental text while the Product Agent streams. */
      delta: string;
      done: boolean;
    }
  | {
      type: "epic.showcase";
      epicId: string;
      markdown: string;
    }
  | {
      type: "run.progress";
      runId: string;
      ticketId: string | null;
      role: (typeof AGENT_ROLES)[number];
      label: string;
      /** 0..1, or null when the step has no measurable progress. */
      fraction: number | null;
    }
  | {
      type: "run.log";
      runId: string;
      /** The ticket the run works on, so the terminal can name it. */
      ticketId?: string | null;
      stream: "stdout" | "stderr";
      line: string;
    }
  | {
      /** What an agent thought or said between its actions on a ticket. */
      type: "run.thought";
      runId: string;
      ticketId: string | null;
      kind: "thinking" | "text";
      text: string;
    }
  | {
      /** A person's note to the agent working a ticket. */
      type: "ticket.note";
      ticketId: string;
      text: string;
    }
  | {
      /**
       * Something an agent found out that the other agents working on the same
       * repository should know: an export renamed, a convention, a trap. Read
       * across every board on the repository (src/lib/coder/shared-notes.ts).
       */
      type: "repo.note";
      ticketId: string;
      text: string;
    }
  | {
      /**
       * An agent saying a shared note helped it or is no longer true. What
       * keeps a useful note in briefings and drops a stale one
       * (src/lib/domain/trail.ts).
       */
      type: "repo.note.rated";
      ticketId: string;
      /** The `seq` of the `repo.note` event rated. */
      noteSeq: number;
      verdict: "helped" | "outdated";
    }
  | {
      /** A person's instruction to the Architect Agent breaking down an Epic. */
      type: "epic.note";
      epicId: string;
      text: string;
    }
  | {
      /**
       * A card's chat is being answered: the column's agent is reading and
       * writing. Nothing moves while it does, so this is the only thing the
       * board has to put a crew on the card for (see `crewPhase` in
       * components/colony/colony.tsx), the way a run's own state does.
       */
      type: "card.chat";
      cardId: string;
      kind: "epic" | "ticket";
      /** "answering" while it writes, "idle" once its reply has landed. */
      state: "answering" | "idle";
    }
  | {
      /** An answer in the board assistant's conversation was marked failed. */
      type: "assistant.failed";
      messageId: string;
    }
  | {
      /** The column's agent answering a person's note on a ticket's chat. */
      type: "ticket.reply";
      ticketId: string;
      /**
       * The agent that answered, such as "Architect Agent". Null for a notice
       * about the message itself, such as no agent being set for the column.
       */
      agent: string | null;
      text: string;
    }
  | {
      /** The plan an agent is working a ticket through, as it stands now. */
      type: "ticket.plan";
      ticketId: string;
      steps: PlanStep[];
    }
  | {
      type: "run.diff";
      runId: string;
      path: string;
      /** Unified diff hunk for the file as it currently stands. */
      patch: string;
    }
  | {
      type: "run.usage";
      runId: string;
      tokensIn: number;
      tokensOut: number;
      costCents: number;
    }
  | {
      type: "run.finished";
      runId: string;
      status: "succeeded" | "failed" | "blocked" | "cancelled";
      error: string | null;
    }
  | {
      type: "ci.status";
      ticketId: string;
      prNumber: number;
      /** "none": the repository runs no CI, so there is nothing to wait for. */
      state: "pending" | "passing" | "failing" | "none";
      checkName: string | null;
    }
  | {
      type: "sandbox.count";
      active: number;
      provider: string;
    }
  | {
      /** A saved agent ran out of usage on its plan, or got it back. */
      type: "agent.limited";
      presetId: string;
      /** ISO time it can work again; null when it can now. */
      until: string | null;
      note: string | null;
    }
  | {
      /** The runner workflow's setup pull request was merged: CLI agents can run. */
      type: "runner.ready";
    }
  | {
      type: "budget.exhausted";
      scope: "run" | "epic" | "global";
      id: string;
      detail: string;
    };

export type FormicEventType = FormicEvent["type"];

/**
 * The frames a board's log can throw away: run output, which is large,
 * high-volume and worthless once it has been read.
 *
 * Not `run.progress`, which is slow-moving enough to be worth keeping and is
 * read back by the ticket activity feed (`ACTIVITY_EVENTS`, `ticket-view.ts`).
 * Nothing here is a state change, and nothing here is read back by anything
 * but a client replaying a stream it fell behind on — see `pruneEvents`.
 */
/** The longest a shared note (`repo.note`) may be. */
export const MAX_SHARED_NOTE = 1_000;

export const PRUNABLE_EVENT_TYPES = ["run.log", "run.diff"] as const;

const PRUNABLE = new Set<string>(PRUNABLE_EVENT_TYPES);

/** Is this one of the frames `pruneEvents` may drop? */
export function isPrunableEventType(type: string): boolean {
  return PRUNABLE.has(type);
}

/** An event as it travels over the wire, with the replay cursor attached. */
export interface SequencedEvent {
  /** Monotonic per project. The client sends this back as Last-Event-ID. */
  seq: number;
  projectId: string;
  at: string;
  event: FormicEvent;
}

/**
 * Not a FormicEvent: the last frame of an event-stream connection the server
 * ends on purpose (see src/app/api/events/route.ts). Its id moves the
 * browser's cursor even when nothing happened, and it tells the client the
 * close that follows is planned, not a dropped connection.
 */
export const STREAM_PAUSE_EVENT = "stream.pause";

/** How long a board waits between short-lived event-stream connections. */
export const STREAM_POLL_MS = 15_000;
